body:
{
  "pains": [
    {
      "id": "pain:paying-more-for-less",
      "statement": "I'm paying $80 a year now and half of what I actually used is behind the paywall, for features I never touch.",
      "element": "b2c:functional:reduces_cost",
      "shape": {
        "surface": "The renewal comes through at a higher price than last year, and features that used to be free now need a subscription.",
        "operational": "They check the renewal price in a browser, downgrade or cancel, and patch the gap with other free tools.",
        "personal": "They feel they're getting zero return on the money and are paying for features they never asked for.",
        "personal_note": "Read from rmhoff and jfranci3 in the TrainerRoad thread. It says what it costs them in money and value, not anything beyond that."
      },
      "workflow": "Opening the Strava app or the strava.com subscription page in January when the annual renewal notice arrives at the new price, then deciding whether the features they actually use (segments, the heatmap) are worth it against the free tier.",
      "type": "felt",
      "confidence": "medium",
      "priority": 1,
      "felt_evidence": {
        "kind": "complaining",
        "what": "In a dated 1-star review from June 2025, a returning user says there is now way too much behind the paywall.",
        "cites": ["src:2"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "The annual renewal notice or charge at the raised price ($60 to $80 a year in the 2023 rise).",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Now my choice looks be to give them $60/yr → $80/year for features I don’t really use.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "It’s not worth it. It gives me zero return on my investment.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "coming back to it after a few years now, there is way too much stuff now behind a paywall.",
              "cites": ["src:2"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Downloaded the free strava app it doesn't do anything, just trying to sell the premium app.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "$20 or more a year extra for the same use, plus the effort of checking whether the subscription still pays its way.",
          "fears": "That they'll keep paying more each year for features they don't use while the ones they do use get locked away.",
          "dream_outcome": "Paying a price that matches the few features they actually use, or getting those features free."
        }
      },
      "relief": {
        "line": "Free and enough. The free version covers every run they care about.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "Only using the free app version so far for my runs and I really like it.",
            "cites": ["src:3"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Worth it. A subscription they'd defend to a friend.",
        "says": [],
        "gap": "Read 1-5 star Trustpilot pages 5 and 10 and the TrainerRoad price thread. Nobody describes a lasting change from paying, and the 5-star reviews praise the free tier."
      },
      "segments": ["seg:serious", "seg:casual"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company kills this. Pricing or packaging would: a cheaper tier for the few features people use, or putting those back in the free tier."
    ,
      "cites": ["src:1", "src:2", "src:3"]
    },
    {
      "id": "pain:garmin-ride-never-reaches-strava",
      "statement": "My Edge recorded the ride and Garmin Connect has it, but it never showed up on Strava.",
      "element": "b2c:functional:integrates",
      "shape": {
        "surface": "The ride is in Garmin Connect, and Strava says it's connected, but the activity isn't there.",
        "operational": "They log out and back in on both apps, reconnect, wait hours, then export the original file from Garmin Connect web and upload it to Strava by hand.",
        "personal": null,
        "personal_note": "Both Garmin forum threads stop at the fix. Neither poster says what the missing ride cost them personally."
      },
      "workflow": "After a ride on a Garmin Edge 520 Plus or 830, the automatic push from Garmin Connect to Strava, at the step where Garmin Connect shows the activity but the Strava feed doesn't.",
      "type": "felt",
      "confidence": "high",
      "priority": 2,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Several riders in the Garmin Connect forum reported the same day's rides failing to reach Strava and asked for a fix.",
        "cites": ["src:4"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "A server error day on either side, when every activity uploaded that day fails to sync.",
          "cites": ["src:4"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "My Edge 830 didn't sync to Strava today, has anyone else had this issue today",
              "cites": ["src:4"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "The connection to Strava is working fine again! But the activity from yesterday hasn’t been uploaded to Strava!",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "My garmin app doesn’t seem to be sending my workout data to strava even though they are showing as connected.",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "A ride missing from their Strava record, plus the time spent reconnecting apps and uploading files by hand.",
          "fears": "That a ride stays off Strava for good unless they notice and fix it themselves.",
          "dream_outcome": "Finish the ride and see it on Strava without touching anything."
        }
      },
      "relief": {
        "line": "It just shows up. Every ride on the Edge lands on Strava by itself.",
        "says": [],
        "gap": "Both Garmin threads end in 'working again' with no rider describing the after-state. The 4 and 5 star reviews on Trustpilot pages 5 and 10 don't mention sync."
      },
      "euphoria": {
        "line": "Never think about it. The sync has been reliable long enough that it isn't a thing anymore.",
        "says": [],
        "gap": "No source found. Riders post about sync when it breaks, not when it works."
      },
      "segments": ["seg:serious"],
      "feature_ref": "feat:track",
      "feature_note": "feat:track records and analyses activities. The pain sits in the device-to-Strava upload that feeds it, so the fix is sync reliability or a visible retry.",
      "cites": ["src:4", "src:5"]
    },
    {
      "id": "pain:koms-taken-by-motors",
      "statement": "I lost my KOMs to someone on an e-bike or a motorcycle, and Strava does nothing about it.",
      "element": "b2c:emotional:rewards_me",
      "shape": {
        "surface": "Their name drops off a segment leaderboard, beaten by a time that's obviously from an e-bike or a motorbike.",
        "operational": "They flag the ride and argue in forums about whether flagging is fair, or stop trusting the leaderboard.",
        "personal": "When someone cheats, the motivation to go out and chase the segment drains away.",
        "personal_note": "From ChrisL in the TrainerRoad flagging thread."
      },
      "workflow": "Opening the Strava segment leaderboard after a summer road ride and finding the KOM taken by a ride logged as a normal bike ride, then using the flag button on that activity.",
      "type": "felt",
      "confidence": "medium",
      "priority": 3,
      "felt_evidence": {
        "kind": "complaining",
        "what": "In a 1-star Trustpilot review, a rider says Strava does nothing about e-bikes ruining the leaderboards.",
        "cites": ["src:3"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "Summer, when e-bikes and motorbikes are out on the same segments.",
          "cites": ["src:6"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Last summer I lost a group of KOMs to a guy riding around on a motorcycle.",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "if someone “cheats” it kind of removes some of that motivation.",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "they do nothing about E bikes or rides being recorded as runs ruining the leaderboards.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Never paid for Strave, never will. The KOM crap is full of cheats motorpacing and eBikes…how worthless.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Segment crowns they earned, and the reason they ride segments hard.",
          "fears": "That the leaderboards become worthless and stay that way.",
          "dream_outcome": "Leaderboards where only human-powered times count, so a KOM means something."
        }
      },
      "relief": {
        "line": "A fair board. When they lose a KOM, it's to someone who rode it.",
        "says": [],
        "gap": "Read the TrainerRoad flagging thread and Trustpilot pages 5 and 10. No rider describes the leaderboards feeling fair again."
      },
      "euphoria": {
        "line": "A crown that counts. A KOM they can point to because everyone trusts the board.",
        "says": [],
        "gap": "No source found in the pages read."
      },
      "segments": ["seg:serious"],
      "feature_ref": "feat:explore",
      "feature_note": "Segments live in feat:explore. The pain is cheating on them, so the fix is detecting e-bikes and motorbikes, not the segments themselves.",
      "cites": ["src:6", "src:3", "src:1"]
    },
    {
      "id": "pain:trial-wont-cancel",
      "statement": "I tried to cancel the free trial and there's no cancel button anywhere, and the annual plan is about to renew.",
      "element": "b2c:functional:avoids_hassles",
      "shape": {
        "surface": "In the app there's no cancel option, just a message pointing to the website, and the website or Google Play doesn't show one either.",
        "operational": "They search Reddit and the support pages, post in the community forum, and get sent to open a support ticket.",
        "personal": null,
        "personal_note": "The posts describe the hunt and the charge, not what it cost the person beyond the money."
      },
      "workflow": "Strava app subscription screen, then strava.com, then Google Play subscriptions, on the day before the free trial converts to an annual plan.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "complaining",
        "what": "In a February 2026 Strava community forum post, a user couldn't find a cancel option anywhere before the annual renewal fired.",
        "cites": ["src:7"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "The free trial is about to convert into an automatic annual renewal.",
          "cites": ["src:7"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "In the app, when I clicked on the subscription, there was no \"cancel\" option,",
              "cites": ["src:7"]
            },
            {
              "situation": "when_looking",
              "verbatim": "I really don't know what to do because the annual plan is about to renew automatically",
              "cites": ["src:7"]
            },
            {
              "situation": "venting",
              "verbatim": "Its almost impossible to cancel the subscription, and they charge you 1 day before your subscription runs out.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "A year's fee they didn't mean to pay, and the time spent hunting for a way out.",
          "fears": "Being charged for a full year before they can reach anyone.",
          "dream_outcome": "Cancel in the app in a couple of taps and see the date it ends."
        }
      },
      "relief": {
        "line": "Three clicks. Cancelling took a moment and nothing more was charged.",
        "says": [],
        "gap": "The one 5-star review praising easy cancellation on Trustpilot page 10 is in French, and only a translation came back. No English after-state quote was found."
      },
      "euphoria": {
        "line": "Trust to try. They start trials freely because leaving is easy.",
        "says": [],
        "gap": "No source found."
      },
      "segments": ["seg:casual"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company covers billing. A cancel button in the app with the end date shown would kill this.",
      "cites": ["src:7", "src:3"]
    },
    {
      "id": "pain:distance-comes-out-wrong",
      "statement": "I run the same distance and Strava gets it wrong, and the day I most want the stats is the day it loses them.",
      "element": "b2c:functional:quality",
      "shape": {
        "surface": "The recorded distance or time doesn't match the run, or the activity doesn't record at all.",
        "operational": "They second-guess every number and stop relying on the app's record of the run.",
        "personal": "The run they most wanted to see the numbers for is the one that goes missing.",
        "personal_note": "From Marc's review on Trustpilot page 10."
      },
      "workflow": "Recording a run with the Strava phone app, then checking distance and time in the activity summary afterwards.",
      "type": "felt",
      "confidence": "low",
      "priority": 5,
      "felt_evidence": {
        "kind": "complaining",
        "what": "In a dated 1-star review from March 2025, a runner says distance on their runs is always incorrect.",
        "cites": ["src:2"]
      },
      "revealed_by": null,
      "triggers": [],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Ive tried to give this app the benefit of the doubt when measuring a distance of a run but it is always incorrect.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Consistently fails to record distance and time.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "it records if it feels like it, usually on a day when I would really like to see the stats it deletes them",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "A record of their training they can't trust, and lost runs.",
          "fears": "That their training log is wrong and they can't measure progress.",
          "dream_outcome": "Every run recorded, with distance and time that match what they ran."
        }
      },
      "relief": {
        "line": "Numbers they trust. The run they did is the run Strava shows.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "accurate data, free account with already several features.",
            "cites": ["src:3"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "A log that proves the progress. Months of trusted numbers to look back on.",
        "says": [],
        "gap": "No source found in the Trustpilot pages read."
      },
      "segments": ["seg:casual"],
      "feature_ref": "feat:track",
      "cites": ["src:2", "src:3"]
    }
  ],
  "awareness": {
    "default": {
      "level": "product",
      "rationale": "Buyers know Strava and its price and are weighing whether the paid features are worth it, not looking for the category.",
      "cites": ["src:1"]
    }
  },
  "stats": [],
  "keywords": [
    "strava not worth it",
    "strava paywall",
    "garmin not uploading to strava",
    "strava e bikes leaderboard",
    "cancel strava subscription",
    "strava distance wrong"
  ],
  "questions": [
    {
      "id": "q:pains-comparison-anxiety",
      "question": "Do your runners say the feed makes them feel watched or judged on slow runs, and do they stop recording because of it?",
      "why": "One runner's essay (src:8) describes the feed weighing on them and stopping recording, but no second source was found, so it isn't a row.",
      "would_change": "pains[]"
    },
    {
      "id": "q:pains-clubs",
      "question": "What do club organisers say is the hardest part of running group rides and runs on Strava, and what do they use instead?",
      "why": "No club organiser voice was found that could be cited, so seg:clubs has no pain.",
      "would_change": "pains[].segments"
    },
    {
      "id": "q:pains-privacy",
      "question": "Do subscribers who use Beacon or privacy zones say they worry about people finding where they live or train?",
      "why": "The only sources found were press coverage of the NC State heatmap research, not buyers, so no safety pain could be written and feat:beacon has no pain pointing at it.",
      "would_change": "pains[]"
    },
    {
      "id": "q:pains-first-call",
      "question": "Which complaint do lapsed subscribers name first when they cancel: price, sync, cheating, or accuracy?",
      "why": "The priority order here is argued from public posts and counts of sources, not from your own churn data.",
      "would_change": "pains[].priority"
    },
    {
      "id": "q:pains-personal",
      "question": "When a ride fails to sync or a trial renews by surprise, what do athletes say it costs them beyond the fix?",
      "why": "The personal rung is null on two pains because no source shows it.",
      "would_change": "pains[].shape.personal"
    }
  ],
  "sources": [
    {
      "id": "src:1",
